/**
 * WASM binding for the `stellar-toml` grammar.
 *
 * `src/parser.c` — generated by `tree-sitter generate` — already defines the
 * entry point `tree_sitter_stellar_toml()` and the external-scanner symbols
 * declared in `src/scanner.c`. A WASM module built from a grammar is just
 * those translation units plus this one, whose only job is to make the entry
 * point visible to the JS host (`WebAssembly.instantiate(...)` then reads
 * `exports.tree_sitter_stellar_toml`) and to document that contract at the
 * conventional path editor plugins look for, `bindings/wasm/binding.c`.
 *
 * Two build paths consume it:
 *
 *   1. `tree-sitter build --wasm` (see `scripts/build-tree-sitter-grammar.mjs`)
 *      compiles `src/parser.c` and `src/scanner.c` and links its own glue; it
 *      does not read this file, which is why changing the grammar name here is
 *      only necessary when the generated `parser.c` entry point changes.
 *   2. An emscripten build, which does compile this file and needs it in order
 *      to export the symbol at all:
 *
 *        emcc -O2 -Isrc -I<tree-sitter>/lib/include \
 *            src/parser.c src/scanner.c bindings/wasm/binding.c \
 *            -sSTANDALONE_WASM -sEXPORTED_FUNCTIONS=_tree_sitter_stellar_toml \
 *            -o tree-sitter-stellar-toml.wasm
 *
 * The compiled `.wasm` is a build artefact and is never committed; run the
 * script above to produce it locally.
 */

#include "tree_sitter/api.h"

/* The name must match `tree_sitter_<snake_case_grammar_name>` exactly. */
const TSLanguage *tree_sitter_stellar_toml(void);
